impl Document {
    pub(crate) fn compare_sdg_abstract_foreign_reference(
        &self,
        other: &Document,
        a: &SdgAbstractForeignReference,
        b: &SdgAbstractForeignReference,
        path: &str,
    ) -> Result<(), String> {
        self.compare_sdg_element_with_gid(other, a.base(), b.base(), path)?;
        self.compare_sdg_attribute(other, a.sdg_attribute(), b.sdg_attribute(), path)?;
        if a.get_dest_meta_class() != b.get_dest_meta_class() {
            return Err(format!("{path}: DEST_META_CLASS mismatch"));
        }
        Ok(())
    }

    pub(crate) fn compare_sdg_abstract_primitive_attribute(
        &self,
        other: &Document,
        a: &SdgAbstractPrimitiveAttribute,
        b: &SdgAbstractPrimitiveAttribute,
        path: &str,
    ) -> Result<(), String> {
        self.compare_sdg_element_with_gid(other, a.base(), b.base(), path)?;
        self.compare_sdg_attribute(other, a.sdg_attribute(), b.sdg_attribute(), path)?;
        self.compare_abstract_value_restriction(
            other,
            a.abstract_value_restriction(),
            b.abstract_value_restriction(),
            path,
        )?;
        Ok(())
    }

    pub(crate) fn compare_sdg_aggregation_with_variation(
        &self,
        other: &Document,
        a: &SdgAggregationWithVariation,
        b: &SdgAggregationWithVariation,
        path: &str,
    ) -> Result<(), String> {
        self.compare_sdg_element_with_gid(other, a.base(), b.base(), path)?;
        self.compare_sdg_attribute(other, a.sdg_attribute(), b.sdg_attribute(), path)?;
        self.compare_abstract_variation_restriction(
            other,
            a.abstract_variation_restriction(),
            b.abstract_variation_restriction(),
            path,
        )?;
        let list_a = a.get_valid_binding_times();
        let list_b = b.get_valid_binding_times();
        if list_a.len() != list_b.len() {
            return Err(format!("{path}: VALID_BINDING_TIMES length mismatch"));
        }
        for (index, (x, y)) in list_a.iter().zip(list_b.iter()).enumerate() {
            if x != y {
                return Err(format!("{path}.VALID_BINDING_TIMES[{index}] mismatch"));
            }
        }
        if a.get_sub_sdg_ref() != b.get_sub_sdg_ref() {
            return Err(format!("{path}: SUB_SDG_REF mismatch"));
        }
        Ok(())
    }

    pub(crate) fn compare_sdg_attribute(
        &self,
        other: &Document,
        a: &SdgAttribute,
        b: &SdgAttribute,
        path: &str,
    ) -> Result<(), String> {
        self.compare_identifiable(other, a.base(), b.base(), path)?;
        self.compare_abstract_multiplicity_restriction(
            other,
            a.abstract_multiplicity_restriction(),
            b.abstract_multiplicity_restriction(),
            path,
        )?;
        Ok(())
    }

    pub(crate) fn compare_sdg_class(
        &self,
        other: &Document,
        a: &SdgClass,
        b: &SdgClass,
        path: &str,
    ) -> Result<(), String> {
        self.compare_sdg_element_with_gid(other, a.base(), b.base(), path)?;
        self.compare_identifiable(other, a.identifiable(), b.identifiable(), path)?;
        if a.get_extends_meta_class() != b.get_extends_meta_class() {
            return Err(format!("{path}: EXTENDS_META_CLASS mismatch"));
        }
        if a.get_caption() != b.get_caption() {
            return Err(format!("{path}: CAPTION mismatch"));
        }
        let list_a = a.get_attributes();
        let list_b = b.get_attributes();
        if list_a.len() != list_b.len() {
            return Err(format!("{path}: ATTRIBUTES length mismatch"));
        }
        for (index, (x, y)) in list_a.iter().zip(list_b.iter()).enumerate() {
            if x != y {
                return Err(format!("{path}.ATTRIBUTES[{index}] mismatch"));
            }
        }
        let list_a = a.get_sdg_constraint_refs();
        let list_b = b.get_sdg_constraint_refs();
        if list_a.len() != list_b.len() {
            return Err(format!("{path}: SDG_CONSTRAINT_REFS length mismatch"));
        }
        for (index, (x, y)) in list_a.iter().zip(list_b.iter()).enumerate() {
            let x = self.ref_types.get(*x).ok_or_else(|| {
                format!("{path}.SDG_CONSTRAINT_REFS[{index}]: id not found in own arena")
            })?;
            let y = other.ref_types.get(*y).ok_or_else(|| {
                format!("{path}.SDG_CONSTRAINT_REFS[{index}]: id not found in other arena")
            })?;
            self.compare_ref_type(other, x, y, &format!("{path}.SDG_CONSTRAINT_REFS[{index}]"))?;
        }
        Ok(())
    }

    pub(crate) fn compare_sdg_def(
        &self,
        other: &Document,
        a: &SdgDef,
        b: &SdgDef,
        path: &str,
    ) -> Result<(), String> {
        self.compare_ar_element(other, a.base(), b.base(), path)?;
        let list_a = a.get_sdg_classes();
        let list_b = b.get_sdg_classes();
        if list_a.len() != list_b.len() {
            return Err(format!("{path}: SDG_CLASSES length mismatch"));
        }
        for (index, (x, y)) in list_a.iter().zip(list_b.iter()).enumerate() {
            let x = self
                .sdg_class
                .get(*x)
                .ok_or_else(|| format!("{path}.SDG_CLASSES[{index}]: id not found in own arena"))?;
            let y = other.sdg_class.get(*y).ok_or_else(|| {
                format!("{path}.SDG_CLASSES[{index}]: id not found in other arena")
            })?;
            self.compare_sdg_class(other, x, y, &format!("{path}.SDG_CLASSES[{index}]"))?;
        }
        Ok(())
    }

    pub(crate) fn compare_sdg_element_with_gid(
        &self,
        _other: &Document,
        a: &SdgElementWithGid,
        b: &SdgElementWithGid,
        path: &str,
    ) -> Result<(), String> {
        Self::compare_ar_object(a.base(), b.base(), path)?;
        if a.get_gid() != b.get_gid() {
            return Err(format!("{path}: GID mismatch"));
        }
        Ok(())
    }

    pub(crate) fn compare_sdg_foreign_reference(
        &self,
        other: &Document,
        a: &SdgForeignReference,
        b: &SdgForeignReference,
        path: &str,
    ) -> Result<(), String> {
        self.compare_sdg_abstract_foreign_reference(other, a.base(), b.base(), path)?;
        Ok(())
    }

    pub(crate) fn compare_sdg_foreign_reference_with_variation(
        &self,
        other: &Document,
        a: &SdgForeignReferenceWithVariation,
        b: &SdgForeignReferenceWithVariation,
        path: &str,
    ) -> Result<(), String> {
        self.compare_sdg_abstract_foreign_reference(other, a.base(), b.base(), path)?;
        self.compare_abstract_variation_restriction(
            other,
            a.abstract_variation_restriction(),
            b.abstract_variation_restriction(),
            path,
        )?;
        let list_a = a.get_valid_binding_times();
        let list_b = b.get_valid_binding_times();
        if list_a.len() != list_b.len() {
            return Err(format!("{path}: VALID_BINDING_TIMES length mismatch"));
        }
        for (index, (x, y)) in list_a.iter().zip(list_b.iter()).enumerate() {
            if x != y {
                return Err(format!("{path}.VALID_BINDING_TIMES[{index}] mismatch"));
            }
        }
        Ok(())
    }

    pub(crate) fn compare_sdg_primitive_attribute(
        &self,
        other: &Document,
        a: &SdgPrimitiveAttribute,
        b: &SdgPrimitiveAttribute,
        path: &str,
    ) -> Result<(), String> {
        self.compare_sdg_abstract_primitive_attribute(other, a.base(), b.base(), path)?;
        Ok(())
    }

    pub(crate) fn compare_sdg_primitive_attribute_with_variation(
        &self,
        other: &Document,
        a: &SdgPrimitiveAttributeWithVariation,
        b: &SdgPrimitiveAttributeWithVariation,
        path: &str,
    ) -> Result<(), String> {
        self.compare_sdg_abstract_primitive_attribute(other, a.base(), b.base(), path)?;
        self.compare_abstract_variation_restriction(
            other,
            a.abstract_variation_restriction(),
            b.abstract_variation_restriction(),
            path,
        )?;
        let list_a = a.get_valid_binding_times();
        let list_b = b.get_valid_binding_times();
        if list_a.len() != list_b.len() {
            return Err(format!("{path}: VALID_BINDING_TIMES length mismatch"));
        }
        for (index, (x, y)) in list_a.iter().zip(list_b.iter()).enumerate() {
            if x != y {
                return Err(format!("{path}.VALID_BINDING_TIMES[{index}] mismatch"));
            }
        }
        Ok(())
    }

    pub(crate) fn compare_sdg_reference(
        &self,
        other: &Document,
        a: &SdgReference,
        b: &SdgReference,
        path: &str,
    ) -> Result<(), String> {
        self.compare_sdg_attribute(other, a.base(), b.base(), path)?;
        if a.get_dest_sdg_ref() != b.get_dest_sdg_ref() {
            return Err(format!("{path}: DEST_SDG_REF mismatch"));
        }
        Ok(())
    }
}
